import { describe, expect, it } from "vitest";
import { toSafeSvgDataUri } from "./qr";

const RAW = `data:image/svg+xml;utf-8,<?xml version="1.0"?>
<!-- Generated by SVGo -->
<svg width="219" height="219" xmlns="http://www.w3.org/2000/svg">
<rect x="12" y="12" width="3" height="3" style="fill:black;stroke:none" />
</svg>`;

describe("toSafeSvgDataUri", () => {
  it("codifica el SVG para que sea una URL válida", () => {
    const uri = toSafeSvgDataUri(RAW);
    expect(uri.startsWith("data:image/svg+xml;charset=utf-8,")).toBe(true);
    expect(() => new URL(uri)).not.toThrow();
    expect(uri).not.toMatch(/[<>"\s]/);
  });

  it("al decodificarla devuelve exactamente el SVG original", () => {
    const uri = toSafeSvgDataUri(RAW);
    const decoded = decodeURIComponent(uri.slice(uri.indexOf(",") + 1));
    expect(decoded).toBe(RAW.slice(RAW.indexOf(",") + 1));
  });

  it("no codifica dos veces algo que ya viene codificado", () => {
    const once = toSafeSvgDataUri(RAW);
    expect(toSafeSvgDataUri(once)).toBe(once);
  });

  it.each([
    "https://example.com/qr.svg",
    "data:text/html,<script>alert(1)</script>",
    "data:image/svg+xml",
  ])("rechaza %j", (value) => {
    expect(() => toSafeSvgDataUri(value)).toThrow();
  });
});
